AND t.tenant_id = #{p.tenantId}
AND t.partition_date >= #{p.partitionFrom}
AND t.partition_date <= #{p.partitionTo}

    AND t.well_group_id IN (
        SELECT og.object_id
        FROM t_object_grant og
        WHERE og.tenant_id = #{p.tenantId}
          AND og.grantee_account = #{p.account}
          AND og.object_type = 'WELL_GROUP'
    )


    AND t.well_group_id = #{p.groupId}


    AND t.monitor_point_id = #{p.monitorPointId}

mapper.select:
SELECT
    t.well_group_id AS group_id,
    g.group_code    AS group_code,
    g.group_name    AS group_name,
    COUNT(*)        AS sample_count,
    MIN(t.pressure_mpa) AS pressure_min,
    MAX(t.pressure_mpa) AS pressure_max,
    AVG(t.pressure_mpa) AS pressure_avg,
    (SELECT t3.pressure_mpa FROM t_wellhead_telemetry t3
        WHERE t3.tenant_id = #{p.tenantId}
          AND t3.partition_date >= #{p.dateFrom}
          AND t3.partition_date <= #{p.dateTo}
          AND t3.well_group_id = t.well_group_id
        ORDER BY t3.reading_time DESC, t3.id DESC
        LIMIT 1) AS latest_pressure,
    MAX(t.reading_time) AS latest_reading_time
FROM t_wellhead_telemetry t
INNER JOIN t_well_group g ON g.id = t.well_group_id

    AND t.tenant_id = #{p.tenantId}
    AND t.partition_date >= #{p.dateFrom}
    AND t.partition_date <= #{p.dateTo}

        AND t.well_group_id IN (
            SELECT og.object_id
            FROM t_object_grant og
            WHERE og.tenant_id = #{p.tenantId}
              AND og.grantee_account = #{p.account}
              AND og.object_type = 'WELL_GROUP'
        )


        AND t.well_group_id IN

            #{gid}



GROUP BY t.well_group_id, g.group_code, g.group_name
ORDER BY g.group_code ASC
